    [SafeStack] Fix crashing with scalable TypeSizes (#180547)

    On e.g. aarch64 the TypeSize of scalar types can have a size that is not
    known at compile time.
    Currently when safestack occurs those it simply crashes as described in
    https://github.com/llvm/llvm-project/issues/175868.

    Since we cannot verify the size at compile time we simply consider the
    access to be unsafe (in regards to safestack).

    Reproducer:
    ```
    #include <arm_sve.h>

    int main() {
        svint32_t vec = svindex_s32(0, 1);
        svint32_t res = svadd_s32_z(svptrue_b32(), vec, vec);
        int32_t buffer[1024];
        svst1_s32(svptrue_b32(), buffer, res);
        return 0;
    }
    ```

diff --git a/llvm/lib/CodeGen/SafeStack.cpp b/llvm/lib/CodeGen/SafeStack.cpp
index 1de5b821376a..152dcca20929 100644
--- a/llvm/lib/CodeGen/SafeStack.cpp
+++ b/llvm/lib/CodeGen/SafeStack.cpp
@@ -177,6 +177,8 @@ class SafeStack {

   bool IsMemIntrinsicSafe(const MemIntrinsic *MI, const Use &U,
                           const Value *AllocaPtr, uint64_t AllocaSize);
+  bool IsAccessSafe(Value *Addr, TypeSize Size, const Value *AllocaPtr,
+                    uint64_t AllocaSize);
   bool IsAccessSafe(Value *Addr, uint64_t Size, const Value *AllocaPtr,
                     uint64_t AllocaSize);

@@ -204,6 +206,16 @@ uint64_t SafeStack::getStaticAllocaAllocationSize(const AllocaInst* AI) {
   return 0;
 }

+bool SafeStack::IsAccessSafe(Value *Addr, TypeSize AccessSize,
+                             const Value *AllocaPtr, uint64_t AllocaSize) {
+  if (AccessSize.isScalable()) {
+    // In case we don't know the size at compile time we cannot verify if the
+    // access is safe.
+    return false;
+  }
+  return IsAccessSafe(Addr, AccessSize.getFixedValue(), AllocaPtr, AllocaSize);
+}
